<?php
declare(strict_types=1);
require_once __DIR__.'/config/communications_step21.php';
$error=null;$msg=null;$m=[];$events=[];$channels=[];$user=[];
try{
    $pdo=business_db();comm_step21_ensure($pdo);$user=security_step17_current_user($pdo);$ctx=comm_step21_context($pdo);$orgId=(int)$ctx['organization_id'];
    if($_SERVER['REQUEST_METHOD']==='POST'){comm_step21_sync_events($pdo,$orgId);$msg='Operational events synchronized into the notification engine.';}
    else comm_step21_sync_events($pdo,$orgId);
    $m=comm_step21_metrics($pdo,$orgId,(int)$user['id']);
    $s=$pdo->prepare("SELECT * FROM communication_events WHERE organization_id=? AND event_status='open' ORDER BY FIELD(severity,'critical','high','normal','low'),occurred_at DESC LIMIT 18");$s->execute([$orgId]);$events=$s->fetchAll();
    $s=$pdo->prepare("SELECT * FROM communication_channel_settings WHERE organization_id=? ORDER BY FIELD(channel,'in_app','email','whatsapp','sms')");$s->execute([$orgId]);foreach($s->fetchAll() as $c){$c['runtime']=comm_step21_channel_runtime($c);$channels[]=$c;}
}catch(Throwable $e){$error=$e->getMessage();}
